import { mkdtemp, readFile, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { programRecoveryData, runProgramRecoveryFixture } from './program-recovery-fixture.mjs';
import { canonicalSha256, sealResultEnvelope, validateTaskEnvelope } from '../skills/wiselink-research-and-synthesize/scripts/validate-payload.mjs';
